import { Hono } from "hono";
import { type AppEnv, err, readBody } from "./app";
import { isOwner } from "../env";
import { getService } from "../catalog";
import { checkDraft, orderCharge, membershipDiscountPct } from "../pricing";
import { placeOrder } from "../orders";
import { PROVIDER_ID_SPACE } from "../providers";
import { quoteCoupon } from "../coupons";

const now = () => Math.floor(Date.now() / 1000);
const json = (v: unknown) => JSON.stringify(v);
const parse = <T>(v: string | null | undefined, fallback: T): T => { try { return v ? JSON.parse(v) as T : fallback; } catch { return fallback; } };
const cleanText = (v: unknown, max = 3000) => typeof v === "string" ? v.trim().slice(0, max) : "";
const positiveInt = (v: unknown) => Number.isSafeInteger(Number(v)) && Number(v) > 0 ? Number(v) : null;

export const v5Customer = new Hono<AppEnv>();
export const v5Admin = new Hono<AppEnv>();
v5Admin.use("*", async (c, next) => {
  if (!isOwner(c.env, c.get("settings"), c.get("user").id)) return err(c, 403, "FORBIDDEN");
  await next();
});

// Customer support tickets. Every customer query is scoped to the authenticated Telegram user.
v5Customer.get("/tickets", async c => {
  const { results } = await c.env.DB.prepare("SELECT id,subject,category,status,priority,created_at,updated_at FROM support_tickets WHERE user_id=?1 ORDER BY updated_at DESC LIMIT 100").bind(c.get("user").id).all();
  return c.json({ items: results });
});
v5Customer.post("/tickets", async c => {
  const b = await readBody<{subject?:unknown;category?:unknown;message?:unknown}>(c);
  const subject = cleanText(b?.subject, 160), message = cleanText(b?.message, 4000), category = cleanText(b?.category, 60) || "general";
  if (!subject || !message) return err(c, 400, "SUBJECT_AND_MESSAGE_REQUIRED");
  const ts = now();
  const result = await c.env.DB.prepare("INSERT INTO support_tickets(user_id,subject,category,status,priority,created_at,updated_at) VALUES(?1,?2,?3,'open','normal',?4,?4)").bind(c.get("user").id, subject, category, ts).run();
  const id = Number(result.meta.last_row_id);
  await c.env.DB.prepare("INSERT INTO ticket_messages(ticket_id,sender_id,is_admin,message,created_at) VALUES(?1,?2,0,?3,?4)").bind(id,c.get("user").id,message,ts).run();
  return c.json({ ok:true,id },201);
});
v5Customer.get("/tickets/:id", async c => {
  const id = positiveInt(c.req.param("id")); if (!id) return err(c,400,"INVALID_ID");
  const ticket = await c.env.DB.prepare("SELECT * FROM support_tickets WHERE id=?1 AND user_id=?2").bind(id,c.get("user").id).first();
  if (!ticket) return err(c,404,"NOT_FOUND");
  const { results } = await c.env.DB.prepare("SELECT id,sender_id,is_admin,message,created_at FROM ticket_messages WHERE ticket_id=?1 AND internal_note=0 ORDER BY id").bind(id).all();
  return c.json({ ticket,messages:results });
});
v5Customer.post("/tickets/:id/reply", async c => {
  const id = positiveInt(c.req.param("id")); const b=await readBody<{message?:unknown}>(c); const message=cleanText(b?.message,4000);
  if(!id||!message) return err(c,400,"INVALID_BODY");
  const ticket=await c.env.DB.prepare("SELECT status FROM support_tickets WHERE id=?1 AND user_id=?2").bind(id,c.get("user").id).first<{status:string}>();
  if(!ticket) return err(c,404,"NOT_FOUND"); if(ticket.status==="closed") return err(c,409,"TICKET_CLOSED");
  const ts=now(); await c.env.DB.batch([c.env.DB.prepare("INSERT INTO ticket_messages(ticket_id,sender_id,is_admin,message,created_at) VALUES(?1,?2,0,?3,?4)").bind(id,c.get("user").id,message,ts),c.env.DB.prepare("UPDATE support_tickets SET status='open',updated_at=?2 WHERE id=?1").bind(id,ts)]);
  return c.json({ok:true});
});

// Promotion listing and participation. Rewards are deliberately not credited from a client request.
v5Customer.get("/promotions", async c => {
  const ts=now(); const {results}=await c.env.DB.prepare("SELECT id,name,kind,description,reward_type,reward_value,starts_at,expires_at,direct_link,config FROM promotions WHERE enabled=1 AND visible=1 AND (starts_at IS NULL OR starts_at<=?1) AND (expires_at IS NULL OR expires_at>?1) ORDER BY id DESC LIMIT 100").bind(ts).all();
  return c.json({items:results});
});
v5Customer.post("/promotions/:id/join", async c => {
  const id=positiveInt(c.req.param("id")); if(!id) return err(c,400,"INVALID_ID"); const ts=now(), uid=c.get("user").id;
  const p=await c.env.DB.prepare("SELECT id,participant_limit,enabled,starts_at,expires_at FROM promotions WHERE id=?1 AND visible=1").bind(id).first<{id:number;participant_limit:number|null;enabled:number;starts_at:number|null;expires_at:number|null}>();
  if(!p||!p.enabled||(p.starts_at&&p.starts_at>ts)||(p.expires_at&&p.expires_at<=ts)) return err(c,404,"PROMOTION_UNAVAILABLE");
  if(p.participant_limit!==null){const count=await c.env.DB.prepare("SELECT COUNT(*) n FROM promotion_participants WHERE promotion_id=?1").bind(id).first<{n:number}>(); if((count?.n??0)>=p.participant_limit) return err(c,409,"PROMOTION_FULL");}
  try { await c.env.DB.prepare("INSERT INTO promotion_participants(promotion_id,user_id,status,joined_at) VALUES(?1,?2,'pending',?3)").bind(id,uid,ts).run(); } catch { return err(c,409,"ALREADY_JOINED"); }
  return c.json({ok:true});
});
v5Customer.post("/promotions/:id/proof", async c => {
  const id=positiveInt(c.req.param("id")); const b=await readBody<{proof?:unknown}>(c); const proof=cleanText(b?.proof,2000); if(!id||!proof) return err(c,400,"PROOF_REQUIRED");
  const r=await c.env.DB.prepare("UPDATE promotion_participants SET proof=?3,status='submitted' WHERE promotion_id=?1 AND user_id=?2 AND status IN ('pending','rejected')").bind(id,c.get("user").id,proof).run();
  if(!r.meta.changes) return err(c,404,"PARTICIPATION_NOT_FOUND_OR_LOCKED"); return c.json({ok:true});
});

// Coupon check returns an eligible discount quote; redemption is linked to order placement in the order workflow.
v5Customer.post("/coupons/validate", async c => {
  const b=await readBody<{code?:unknown;serviceId?:unknown;link?:unknown;quantity?:unknown;fields?:Record<string,string>;dripMinutes?:number}>(c);
  const code=cleanText(b?.code,80).toUpperCase(),serviceId=positiveInt(b?.serviceId);
  if(!code||!serviceId||typeof b?.link!=="string")return err(c,400,"SERVICE_LINK_AND_COUPON_REQUIRED");
  const svc=await getService(c.env,c.get("settings"),c.get("lang"),serviceId);if(!svc)return err(c,404,"SERVICE_NOT_FOUND");
  const checked=checkDraft({...svc,type_key:svc.typeKey,dripfeed:!!svc.dripFeed,dripMax:svc.dripFeed?.max_total_minutes??null},{link:b.link,quantity:b.quantity===undefined?undefined:Number(b.quantity),fields:b.fields,dripMinutes:b.dripMinutes});
  if("error" in checked)return err(c,400,checked.error,checked.details);
  const base=orderCharge(svc.rate,checked.quantity,svc.quantityMode),vip=await membershipDiscountPct(c.env,c.get("user").id,svc.id,svc.category),subtotal=Math.max(1,Math.floor(base*(1-vip/100)));
  const quote=await quoteCoupon(c.env,c.get("user").id,code,subtotal,svc.id,svc.category);if("error" in quote)return err(c,400,quote.error,quote.details);
  return c.json({ok:true,code:quote.code,subtotal,discount:quote.discount,finalAmount:quote.finalAmount,membershipDiscountPct:vip,quantity:checked.quantity});
});

