v5Admin.post("/promotions/:id/review",async c=>{
 const id=positiveInt(c.req.param("id"));const b=await readBody<{userId?:unknown;approve?:unknown;reason?:unknown}>(c);const uid=positiveInt(b?.userId);if(!id||!uid||typeof b?.approve!=="boolean")return err(c,400,"INVALID_BODY");
 const ts=now(),actor=c.get("user").id,reason=cleanText(b.reason,1000);const campaign=await c.env.DB.prepare("SELECT reward_type,reward_value,budget,spent FROM promotions WHERE id=?1").bind(id).first<{reward_type:string;reward_value:number;budget:number|null;spent:number}>();if(!campaign)return err(c,404,"PROMOTION_NOT_FOUND");
 if(!b.approve){const r=await c.env.DB.prepare("UPDATE promotion_participants SET status='rejected',rejection_reason=?3,reviewed_at=?4 WHERE promotion_id=?1 AND user_id=?2 AND status='submitted'").bind(id,uid,reason,ts).run();if(!r.meta.changes)return err(c,409,"NOT_SUBMITTED");await c.env.DB.prepare("INSERT INTO audit_logs(actor_id,action,entity,entity_id,details,created_at) VALUES(?1,'promotion_review','participant',?2,?3,?4)").bind(actor,`${id}:${uid}`,json({status:"rejected",reason}),ts).run();return c.json({ok:true,status:"rejected"});}
 const amount=Math.max(0,Number(campaign.reward_value)||0);if(campaign.budget!==null&&campaign.spent+amount>campaign.budget)return err(c,409,"CAMPAIGN_BUDGET_EXCEEDED");
 const statements=[c.env.DB.prepare("UPDATE promotion_participants SET status='approved',rejection_reason=NULL,reviewed_at=?3 WHERE promotion_id=?1 AND user_id=?2 AND status='submitted' AND EXISTS(SELECT 1 FROM promotions WHERE id=?1 AND (budget IS NULL OR spent+?4<=budget))").bind(id,uid,ts,amount),c.env.DB.prepare("UPDATE promotions SET spent=spent+?2 WHERE id=?1 AND changes()=1 AND EXISTS(SELECT 1 FROM promotion_participants WHERE promotion_id=?1 AND user_id=?3 AND status='approved') AND NOT EXISTS(SELECT 1 FROM promotion_rewards WHERE promotion_id=?1 AND user_id=?3) AND (budget IS NULL OR spent+?2<=budget)").bind(id,amount,uid),c.env.DB.prepare("INSERT INTO promotion_rewards(promotion_id,user_id,reward_type,amount,created_at) SELECT ?1,?2,?3,?4,?5 WHERE changes()=1 AND EXISTS(SELECT 1 FROM promotion_participants WHERE promotion_id=?1 AND user_id=?2 AND status='approved') AND NOT EXISTS(SELECT 1 FROM promotion_rewards WHERE promotion_id=?1 AND user_id=?2)").bind(id,uid,campaign.reward_type,amount,ts)];
 if(campaign.reward_type==="balance"&&amount>0){statements.push(c.env.DB.prepare("UPDATE users SET balance=balance+?3 WHERE id=?1 AND EXISTS(SELECT 1 FROM promotion_rewards WHERE promotion_id=?2 AND user_id=?1 AND reward_type='balance') AND NOT EXISTS(SELECT 1 FROM ledger WHERE user_id=?1 AND kind='promotion' AND ref=?2)").bind(uid,id,amount));statements.push(c.env.DB.prepare("INSERT INTO ledger(user_id,delta,kind,ref,note,created_at) SELECT ?1,?2,'promotion',?3,?4,?5 WHERE EXISTS(SELECT 1 FROM promotion_rewards WHERE promotion_id=?3 AND user_id=?1 AND reward_type='balance') AND NOT EXISTS(SELECT 1 FROM ledger WHERE user_id=?1 AND kind='promotion' AND ref=?3)").bind(uid,amount,id,`Promotion ${id} reward`,ts));}
 statements.push(c.env.DB.prepare("INSERT INTO audit_logs(actor_id,action,entity,entity_id,details,created_at) VALUES(?1,'promotion_review','participant',?2,?3,?4)").bind(actor,`${id}:${uid}`,json({status:"approved",rewardType:campaign.reward_type,amount}),ts));await c.env.DB.batch(statements);
 const participant=await c.env.DB.prepare("SELECT status FROM promotion_participants WHERE promotion_id=?1 AND user_id=?2").bind(id,uid).first<{status:string}>();if(participant?.status!=="approved")return err(c,409,"NOT_SUBMITTED");return c.json({ok:true,status:"approved",rewardType:campaign.reward_type,rewardSettled:campaign.reward_type==="balance",rewardAmount:campaign.reward_type==="balance"?amount:0});
});

