// AI-assisted order preparation and confirmation: drafts do not debit the wallet or contact providers.
v5Customer.post("/ai/drafts",async c=>{const b=await readBody<{serviceId?:unknown;link?:unknown;quantity?:unknown;fields?:unknown;dripMinutes?:unknown}>(c);const serviceId=positiveInt(b?.serviceId);if(!serviceId||typeof b?.link!=="string")return err(c,400,"INVALID_BODY");const svc=await getService(c.env,c.get("settings"),c.get("lang"),serviceId);if(!svc)return err(c,404,"SERVICE_NOT_FOUND");const check=checkDraft({...svc,type_key:svc.typeKey,dripfeed:!!svc.dripFeed,dripMax:svc.dripFeed?.max_total_minutes??null},{link:b.link,quantity:Number(b.quantity),fields:b.fields as Record<string,string>|undefined,dripMinutes:b.dripMinutes as number|undefined});if("error"in check)return err(c,400,check.error,check.details);const basePrice=orderCharge(svc.rate,check.quantity,svc.quantityMode);const pct=await membershipDiscountPct(c.env,c.get("user").id,svc.id,svc.category);const price=Math.max(1,Math.floor(basePrice*(1-pct/100)));const ts=now(),expires=ts+600;const r=await c.env.DB.prepare("INSERT INTO ai_order_drafts(user_id,service_id,link,quantity,price,status,expires_at,created_at,fields,drip_minutes) VALUES(?1,?2,?3,?4,?5,'draft',?6,?7,?8,?9)").bind(c.get("user").id,svc.id,check.link,check.quantity,price,expires,ts,json(check.fields),b.dripMinutes??null).run();return c.json({draftId:r.meta.last_row_id,service:{id:svc.id,name:svc.name},link:check.link,quantity:check.quantity,fields:check.fields,basePrice,price,discountPct:pct,savings:basePrice-price,balance:c.get("user").balance,expiresAt:expires,requiresConfirmation:true});});
v5Customer.get("/ai/drafts/:id",async c=>{const id=positiveInt(c.req.param("id"));if(!id)return err(c,400,"INVALID_ID");const d=await c.env.DB.prepare("SELECT * FROM ai_order_drafts WHERE id=?1 AND user_id=?2").bind(id,c.get("user").id).first();if(!d)return err(c,404,"NOT_FOUND");return c.json({draft:d});});
v5Customer.post("/ai/drafts/:id/confirm",async c=>{const id=positiveInt(c.req.param("id"));if(!id)return err(c,400,"INVALID_ID");const uid=c.get("user").id,ts=now();const draft=await c.env.DB.prepare("SELECT * FROM ai_order_drafts WHERE id=?1 AND user_id=?2 AND status='draft' AND expires_at>?3").bind(id,uid,ts).first<any>();if(!draft)return err(c,409,"DRAFT_EXPIRED_OR_ALREADY_USED");const svc=await getService(c.env,c.get("settings"),c.get("lang"),Number(draft.service_id));if(!svc)return err(c,404,"SERVICE_NOT_AVAILABLE");const check=checkDraft({...svc,type_key:svc.typeKey,dripfeed:!!svc.dripFeed,dripMax:svc.dripFeed?.max_total_minutes??null},{link:draft.link,quantity:draft.quantity,fields:parse<Record<string,string>>(draft.fields,{}),dripMinutes:draft.drip_minutes??undefined});if("error"in check)return err(c,400,check.error,check.details);const claim=await c.env.DB.prepare("UPDATE ai_order_drafts SET status='confirming' WHERE id=?1 AND user_id=?2 AND status='draft'").bind(id,uid).run();if(!claim.meta.changes)return err(c,409,"DRAFT_ALREADY_CONFIRMED");try{const order=await placeOrder(c.env,uid,svc,check.link,check.quantity,check.fields,draft.drip_minutes??undefined,Number(draft.price));await c.env.DB.prepare("UPDATE ai_order_drafts SET status='confirmed',order_id=?2 WHERE id=?1").bind(id,order.id).run();return c.json({ok:true,orderId:order.id,order});}catch(e){await c.env.DB.prepare("UPDATE ai_order_drafts SET status='failed' WHERE id=?1 AND status='confirming'").bind(id).run().catch(()=>undefined);throw e;}});
