v5Customer.post("/free-services/:id/claim",async c=>{
 const id=positiveInt(c.req.param("id")); if(!id)return err(c,400,"INVALID_ID");
 const body=await readBody<{link?:unknown}>(c); const link=cleanText(body?.link,2048); if(!link)return err(c,400,"LINK_REQUIRED");
 const uid=c.get("user").id,ts=now();
 const camp=await c.env.DB.prepare("SELECT * FROM free_service_campaigns WHERE id=?1 AND enabled=1 AND (starts_at IS NULL OR starts_at<=?2) AND (expires_at IS NULL OR expires_at>?2)").bind(id,ts).first<any>();
 if(!camp)return err(c,404,"CAMPAIGN_UNAVAILABLE");
 const svc=await getService(c.env,c.get("settings"),c.get("lang"),Number(camp.service_id)); if(!svc)return err(c,409,"SERVICE_UNAVAILABLE");
 if(Math.floor(Number(svc.id)/PROVIDER_ID_SPACE)!==Number(camp.provider_id))return err(c,409,"CAMPAIGN_PROVIDER_MISMATCH");
 const checked=checkDraft({...svc,type_key:svc.typeKey,dripfeed:!!svc.dripFeed,dripMax:svc.dripFeed?.max_total_minutes??null},{link,quantity:Number(camp.quantity)});
 if("error" in checked)return err(c,400,checked.error,checked.details);
 const per=await c.env.DB.prepare("SELECT COUNT(*) n FROM free_service_claims WHERE campaign_id=?1 AND user_id=?2").bind(id,uid).first<any>();
 if((per?.n??0)>=Number(camp.per_user_limit||1))return err(c,409,"CLAIM_LIMIT");
 const tz=cleanText(camp.timezone,60)||"UTC";let claimDate:string;
 try{claimDate=new Intl.DateTimeFormat("en-CA",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date(ts*1000));}catch{claimDate=new Date(ts*1000).toISOString().slice(0,10);}
 if(camp.daily_limit){const daily=await c.env.DB.prepare("SELECT COUNT(*) n FROM free_service_claims WHERE campaign_id=?1 AND claim_date=?2").bind(id,claimDate).first<any>();if((daily?.n??0)>=Number(camp.daily_limit))return err(c,409,"DAILY_LIMIT");}
 const estimatedCost=svc.quantityMode==="fixed"?Number(svc.cost):Math.ceil(Number(svc.cost)*checked.quantity/1000);
 const spent=await c.env.DB.prepare("SELECT COALESCE(SUM(cost),0) amount FROM free_service_claims WHERE campaign_id=?1").bind(id).first<any>();
 if(camp.budget!==null&&Number(spent?.amount||0)+estimatedCost>Number(camp.budget))return err(c,409,"CAMPAIGN_BUDGET_EXHAUSTED");
 let claimId:number;
 try{const reservation=await c.env.DB.prepare(`INSERT INTO free_service_claims(campaign_id,user_id,quantity,claimed_at,claim_date,cost)
   SELECT ?1,?2,?3,?4,?5,?6 WHERE EXISTS(SELECT 1 FROM free_service_campaigns f WHERE f.id=?1 AND f.enabled=1
    AND (f.starts_at IS NULL OR f.starts_at<=?4) AND (f.expires_at IS NULL OR f.expires_at>?4)
    AND (f.budget IS NULL OR (SELECT COALESCE(SUM(x.cost),0) FROM free_service_claims x WHERE x.campaign_id=f.id)+?6<=f.budget)
    AND (SELECT COUNT(*) FROM free_service_claims x WHERE x.campaign_id=f.id AND x.user_id=?2)<f.per_user_limit
    AND (f.daily_limit IS NULL OR (SELECT COUNT(*) FROM free_service_claims x WHERE x.campaign_id=f.id AND x.claim_date=?5)<f.daily_limit)
   )`).bind(id,uid,checked.quantity,ts,claimDate,estimatedCost).run();if(!reservation.meta.changes)return err(c,409,"CLAIM_LIMIT_OR_BUDGET_REACHED");claimId=Number(reservation.meta.last_row_id);}catch{return err(c,409,"CLAIM_ALREADY_RECORDED");}
 try{
  const order=await placeOrder(c.env,uid,svc,checked.link,checked.quantity,checked.fields,undefined,0);
  if(["failed","cancelled"].includes(order.status))throw new Error("FREE_SERVICE_ORDER_FAILED");
  await c.env.DB.prepare("UPDATE free_service_claims SET order_id=?2,cost=?3 WHERE id=?1").bind(claimId,order.id,Number(order.cost||estimatedCost)).run();
  return c.json({ok:true,claimRecorded:true,orderId:order.id,quantity:checked.quantity,status:order.status});
 }catch(e){
  // A provider timeout can mean it accepted the order but the response was lost. Keep the claim
  // reserved when an order row exists, preventing a second provider submission from the same claim.
  const uncertain=await c.env.DB.prepare("SELECT id,status,cost FROM orders WHERE user_id=?1 AND service_id=?2 AND link=?3 AND created_at>=?4 ORDER BY id DESC LIMIT 1").bind(uid,svc.id,checked.link,ts-60).first<any>().catch(()=>null);
  if(uncertain){await c.env.DB.prepare("UPDATE free_service_claims SET order_id=?2,cost=COALESCE(?3,cost) WHERE id=?1").bind(claimId,uncertain.id,uncertain.cost).run().catch(()=>{});return err(c,502,"FREE_SERVICE_ORDER_UNCERTAIN",{orderId:uncertain.id,status:uncertain.status,notice:"Claim remains reserved to prevent duplicate provider fulfillment. Contact support for review."});}
  await c.env.DB.prepare("DELETE FROM free_service_claims WHERE id=?1").bind(claimId).run().catch(()=>{});
  return err(c,502,"FREE_SERVICE_FULFILLMENT_FAILED",{message:(e as Error).message.slice(0,160)});
 }
});

