 const tables=["users","orders","ledger","payments","payment_gateway_events","topup_requests","services","service_names","category_rules","category_icons","currencies","referrals","assets","price_changes","provider_health","membership_levels","membership_history","membership_overrides","coupons","coupon_redemptions","support_tickets","ticket_messages","ticket_attachments","promotions","promotion_participants","promotion_rewards","free_service_campaigns","free_service_claims","loyalty_accounts","loyalty_transactions","loyalty_checkins","loyalty_settings","cashback_transactions","message_templates","broadcast_campaigns","broadcast_deliveries","broadcast_drafts","broadcast_history","ai_sessions","ai_order_drafts","ai_usage_logs","legal_policies","policy_acceptances","maintenance_settings","maintenance_events","automation_jobs","audit_logs","backup_history","order_events","user_notes","user_tags"];
