// Customer/order exports are owner-only and capped to avoid oversized Worker responses.
const csvCell=(v:unknown)=>{let x=v===null||v===undefined?"":String(v);if(/^[=+\-@\t\r]/.test(x))x="'"+x;return `"${x.replace(/"/g,'""')}"`;};
