v5Admin.post("/backup/restore/preview",async c=>{const b=await readBody<{format?:unknown;data?:unknown;createdAt?:unknown}>(c);if(b?.format!=="cp-smm-v5-json"||!b.data||typeof b.data!=="object"||Array.isArray(b.data))return err(c,400,"INVALID_BACKUP_FORMAT");const data=b.data as Record<string,unknown>,allow=new Set(["users","orders","ledger","payments","payment_gateway_events","topup_requests","services","service_names","category_rules","category_icons","currencies","referrals","assets","price_changes","provider_health","membership_levels","membership_history","membership_overrides","coupons","coupon_redemptions","support_tickets","ticket_messages","ticket_attachments","promotions","promotion_participants","promotion_rewards","free_service_campaigns","free_service_claims","loyalty_accounts","loyalty_transactions","loyalty_checkins","loyalty_settings","cashback_transactions","message_templates","broadcast_campaigns","broadcast_deliveries","broadcast_drafts","broadcast_history","ai_sessions","ai_order_drafts","ai_usage_logs","legal_policies","policy_acceptances","maintenance_settings","maintenance_events","automation_jobs","audit_logs","backup_history","order_events","user_notes","user_tags","providers","payment_methods","settings_safe"]);const tableReports:Record<string,unknown>={};let total=0;for(const [table,rows] of Object.entries(data)){if(!allow.has(table))return err(c,400,"UNSUPPORTED_TABLE",{table});if(!Array.isArray(rows))return err(c,400,"INVALID_TABLE_DATA",{table});if(rows.length>50000)return err(c,413,"TABLE_TOO_LARGE",{table});total+=rows.length;tableReports[table]={rows:rows.length,columns:rows.length&&typeof rows[0]==="object"?Object.keys(rows[0] as object):[]};}if(total>100000)return err(c,413,"BACKUP_TOO_LARGE",{totalRows:total});return c.json({valid:true,format:b.format,createdAt:b.createdAt,totalRows:total,tables:tableReports,warning:"Validation preview only; no data is changed. Use the explicit merge endpoint for insert-only restore. Credentials are omitted from backup exports."});});
// Safe additive restore: inserts missing records only, never deletes or overwrites existing balances/settings.
// Restore is intentionally bounded to one transactional batch and requires an explicit confirmation string.
v5Admin.post("/backup/restore/merge",async c=>{
 const b=await readBody<{format?:unknown;data?:unknown;confirm?:unknown}>(c);
 if(b?.format!=="cp-smm-v5-json"||!b.data||typeof b.data!=="object"||Array.isArray(b.data))return err(c,400,"INVALID_BACKUP_FORMAT");
 if(b.confirm!=="MERGE_BACKUP")return err(c,400,"CONFIRMATION_REQUIRED");
 const data=b.data as Record<string,unknown>;
 const bytes=JSON.stringify(b.data).length;if(bytes>5_000_000)return err(c,413,"BACKUP_TOO_LARGE");
 const skip=new Set(["settings_safe","category_summary","rate_limits","webhook_events","backup_history"]);
 const allowed=new Set(["users","orders","ledger","payments","payment_gateway_events","topup_requests","services","service_names","category_rules","category_icons","currencies","referrals","assets","price_changes","provider_health","membership_levels","membership_history","membership_overrides","coupons","coupon_redemptions","support_tickets","ticket_messages","ticket_attachments","promotions","promotion_participants","promotion_rewards","free_service_campaigns","free_service_claims","loyalty_accounts","loyalty_transactions","loyalty_checkins","loyalty_settings","cashback_transactions","message_templates","broadcast_campaigns","broadcast_deliveries","broadcast_drafts","broadcast_history","ai_sessions","ai_order_drafts","ai_usage_logs","legal_policies","policy_acceptances","maintenance_settings","maintenance_events","automation_jobs","audit_logs","order_events","user_notes","user_tags","providers","payment_methods"]);
 const statements:any[]=[];let ignoredTables=0,totalRows=0;
 for(const [table,rows] of Object.entries(data)){
  if(skip.has(table)){ignoredTables++;continue;}
  if(!allowed.has(table))return err(c,400,"UNSUPPORTED_TABLE",{table});
  if(!Array.isArray(rows))return err(c,400,"INVALID_TABLE_DATA",{table});
  if(rows.length>750)return err(c,413,"RESTORE_TABLE_TOO_LARGE",{table,rows:rows.length,limit:750});
  const cols=(await c.env.DB.prepare(`PRAGMA table_info(${table})`).all<{name:string}>()).results.map(x=>x.name);
  for(const row of rows){if(!row||typeof row!=="object"||Array.isArray(row))return err(c,400,"INVALID_ROW",{table});let record={...(row as Record<string,unknown>)};
   // Restore provider/payment configuration without credentials. Provider rows stay disabled until reconfigured.
   if(table==="providers"){record.api_key="";record.enabled=0;}
   if(table==="payment_methods"){record.api_key="";if(record.kind==="api")record.enabled=0;}
   const keys=Object.keys(record);if(keys.some(k=>!cols.includes(k)))return err(c,400,"INVALID_COLUMN",{table});if(!keys.length)continue;
   const insertMode=(table==="providers"||table==="payment_methods")?"INSERT OR REPLACE":"INSERT OR IGNORE";
   statements.push(c.env.DB.prepare(`${insertMode} INTO ${table}(${keys.map(k=>`\"${k}\"`).join(",")}) VALUES(${keys.map(()=>"?").join(",")})`).bind(...keys.map(k=>record[k]===undefined?null:record[k])));totalRows++;
  }
 }
 // Import only whitelisted settings; secrets and owner/bootstrap keys are excluded.
 const safeSettings=new Set(["default_markup_pct","stars_per_usd","min_topup_stars","max_topup_stars","sync_enabled","sync_every_hours","auto_enable_new","only_timed","low_balance","support_username","channel_url","channel_id","channel_gate","referral_enabled","referral_reward_stars","referral_daily_cap","terms_text","app_url","welcome_photo","bot_username","brand_name","brand_preset","brand_accent","website_url","terms_url","welcome_text","bot_messages","custom_emoji","button_icons","logo_ver","banner_ver","default_currency","maintenance_enabled","maintenance_message","maintenance_return_at","ai_enabled","ai_model","ai_daily_limit","broadcast_enabled","free_service_enabled"]);
 const settings=data.settings_safe;if(Array.isArray(settings))for(const row of settings){if(row&&typeof row==="object"&&!Array.isArray(row)){const r=row as Record<string,unknown>;if(typeof r.key==="string"&&safeSettings.has(r.key)&&typeof r.value==="string")statements.push(c.env.DB.prepare("INSERT OR IGNORE INTO settings(key,value) VALUES(?1,?2)").bind(r.key,r.value));}}
 if(totalRows>750||statements.length>900)return err(c,413,"RESTORE_BATCH_TOO_LARGE",{rows:totalRows,statements:statements.length,limit:750});
 try{if(statements.length)await c.env.DB.batch(statements);const ts=now();await c.env.DB.prepare("INSERT INTO backup_history(kind,status,details,created_at) VALUES('restore_merge','completed',?1,?2)").bind(json({insertStatements:statements.length,rowsConsidered:totalRows,excludedSensitiveConfig:true,skippedTables:ignoredTables}),ts).run();return c.json({ok:true,mode:"merge_insert_only",statements:statements.length,rowsConsidered:totalRows,warning:"Existing rows are preserved. Provider API keys and payment API keys were blanked; providers and API payment methods are disabled until reconfigured. Conflicting IDs were skipped."});}
 catch(e){await c.env.DB.prepare("INSERT INTO backup_history(kind,status,details,created_at) VALUES('restore_merge','failed',?1,?2)").bind(json({error:String((e as Error).message).slice(0,500),rowsConsidered:totalRows}),now()).run().catch(()=>undefined);return err(c,400,"RESTORE_MERGE_FAILED");}
});

v5Admin.get("/analytics",async c=>{const [coupons,promotions,tickets,membership,loyalty,freeClaims]=await Promise.all([c.env.DB.prepare("SELECT COUNT(*) coupons,COALESCE(SUM(discount_amount),0) discounts FROM coupon_redemptions").first<any>(),c.env.DB.prepare("SELECT COUNT(*) campaigns,COALESCE(SUM(spent),0) spent,COALESCE(SUM((SELECT COUNT(*) FROM promotion_participants x WHERE x.promotion_id=p.id)),0) participants FROM promotions p").first<any>(),c.env.DB.prepare("SELECT COUNT(*) total,SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) open,SUM(CASE WHEN status='closed' THEN 1 ELSE 0 END) closed FROM support_tickets").first<any>(),c.env.DB.prepare("SELECT COUNT(*) levels,(SELECT COUNT(*) FROM membership_overrides) manuallyAssigned FROM membership_levels l").first<any>(),c.env.DB.prepare("SELECT COALESCE(SUM(points),0) pointsGranted,COUNT(DISTINCT user_id) users FROM loyalty_transactions").first<any>(),c.env.DB.prepare("SELECT COUNT(*) claims,COALESCE(SUM(cost),0) trackedCost FROM free_service_claims").first<any>()]);return c.json({coupons,promotions,tickets,membership,loyalty,freeServices:freeClaims});});
// Date-range analytics for financial and operational reporting. Values are micro-USD unless noted.
v5Admin.get("/analytics/report",async c=>{
 const parseDate=(raw:string|undefined,def:number)=>{if(!raw)return def;const n=Number(raw);if(Number.isFinite(n)&&n>0)return Math.floor(n);const d=Date.parse(raw);return Number.isFinite(d)?Math.floor(d/1000):def;};
 const end=parseDate(c.req.query("end"),now()),start=parseDate(c.req.query("start"),end-30*86400);if(start>=end)return err(c,400,"INVALID_DATE_RANGE");
 const [orders,statuses,daily,topServices,topCategories,newUsers,activeUsers,payments,ledger,providerCost]=await Promise.all([
  c.env.DB.prepare("SELECT COUNT(*) total,COALESCE(SUM(charge),0) gross,COALESCE(SUM(refunded),0) refunds,COALESCE(SUM(cost),0) costs,COALESCE(SUM(charge-refunded-COALESCE(cost,0)),0) estimatedProfit,COALESCE(SUM(CASE WHEN status='completed' THEN charge-refunded ELSE 0 END),0) completedRevenue FROM orders WHERE created_at>=?1 AND created_at<?2").bind(start,end).first<any>(),
  c.env.DB.prepare("SELECT status,COUNT(*) count,COALESCE(SUM(charge),0) charge,COALESCE(SUM(refunded),0) refunded FROM orders WHERE created_at>=?1 AND created_at<?2 GROUP BY status ORDER BY count DESC").bind(start,end).all(),
  c.env.DB.prepare("SELECT date(created_at,'unixepoch') day,COUNT(*) orders,COALESCE(SUM(charge-refunded),0) netRevenue FROM orders WHERE created_at>=?1 AND created_at<?2 GROUP BY day ORDER BY day").bind(start,end).all(),
  c.env.DB.prepare("SELECT service_name,COUNT(*) orders,COALESCE(SUM(charge-refunded),0) revenue,COALESCE(SUM(cost),0) cost FROM orders WHERE created_at>=?1 AND created_at<?2 GROUP BY service_id,service_name ORDER BY revenue DESC LIMIT 20").bind(start,end).all(),
  c.env.DB.prepare("SELECT category,COUNT(*) orders,COALESCE(SUM(charge-refunded),0) revenue FROM orders WHERE created_at>=?1 AND created_at<?2 GROUP BY category ORDER BY revenue DESC LIMIT 20").bind(start,end).all(),
  c.env.DB.prepare("SELECT COUNT(*) count FROM users WHERE created_at>=?1 AND created_at<?2").bind(start,end).first<any>(),
  c.env.DB.prepare("SELECT COUNT(DISTINCT user_id) count FROM orders WHERE created_at>=?1 AND created_at<?2").bind(start,end).first<any>(),
  c.env.DB.prepare("SELECT COUNT(*) payments,COALESCE(SUM(stars),0) stars,COALESCE(SUM(amount),0) credited FROM payments WHERE status='paid' AND paid_at>=?1 AND paid_at<?2").bind(start,end).first<any>(),
  c.env.DB.prepare("SELECT kind,COUNT(*) count,COALESCE(SUM(delta),0) delta FROM ledger WHERE created_at>=?1 AND created_at<?2 GROUP BY kind").bind(start,end).all(),
  c.env.DB.prepare("SELECT provider_id,COUNT(*) orders,COALESCE(SUM(cost),0) cost FROM orders WHERE created_at>=?1 AND created_at<?2 AND provider_id IS NOT NULL GROUP BY provider_id ORDER BY cost DESC").bind(start,end).all()
 ]);
 return c.json({range:{start,end},currencyUnit:"micro-USD",orders,statuses:statuses.results,daily:daily.results,topServices:topServices.results,topCategories:topCategories.results,newUsers:newUsers?.count??0,activeCustomers:activeUsers?.count??0,payments,ledger:ledger.results,providerCost:providerCost.results});
});
